    if port_paths:
        # Original Section ports use the general cyclic topology, including
        # four-way rings with straight/S continuations. The legacy four-side
        # route below remains unchanged for the existing input contract.
        return build(**options,multisided=True,continuations=continuations,port_paths=True,regularize_mesh=regularize_mesh)
    ordinary=build(**options)
    name=ordinary.name+' / Adaptive side count v1'
    if continuations:name+=' / Curb continuations v2'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for socket in ordinary.interface.items_tree:
        if socket.item_type=='SOCKET':
            g.socket(socket.name,socket.socket_type,socket.in_out,default=getattr(socket,'default_value',None))
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput');calls=[]
    for tree in (ordinary,build(**options,multisided=True,continuations=continuations)):
        call=g.node('GeometryNodeGroup');call.node_tree=tree
        for socket in tree.interface.items_tree:
            if socket.item_type=='SOCKET' and socket.in_out=='INPUT':g.bind(inp.outputs[socket.name],call.inputs[socket.name])
        calls.append(call)
    four=g.math('COMPARE',c._count(g,inp.outputs['Approaches']),4.)
