    if port_paths:
        return (framed(**options,adaptive_sides=True,continuations=True,port_paths=True) if local_frames else
                adaptive(**options,continuations=True,port_paths=True))
    if local_frames:
        return framed(**options,adaptive_sides=general_patches,continuations=general_patches)
    return adaptive(**options,continuations=True) if general_patches else build(**options)


